                      <span className="text-gray-900 font-bold">
                        {quote.usableArea ? (quote.usableArea.trim().match(/^\d+(\.\d+)?$/) ? `${quote.usableArea} å¹³æ–¹å‘` : quote.usableArea) : 'è«‹åƒé–±åˆç´„æ˜ç´°'}
                      </span>
