  // Upload and parse a single quotation JSON and add it to the database
  const handleImportSingleQuote = (event: ChangeEvent<HTMLInputElement>) => {
    const fileReader = new FileReader();
    const files = event.target.files;
    if (!files || files.length === 0) return;

    fileReader.onload = (e) => {
      try {
        const resultString = e.target?.result as string;
        const parsed = JSON.parse(resultString) as Partial<Quotation>;
        
        if (!parsed || typeof parsed !== 'object') {
          showToast('éæœ‰æ•ˆ JSON ç‰©ä»¶æ ¼å¼', 'error');
          return;
        }

        if (!parsed.id || !parsed.customerName || !parsed.items || !Array.isArray(parsed.items)) {
          showToast('è©²æª”æ¡ˆéåˆç´„å ±åƒ¹å–® JSON æ ¼å¼ï¼ˆç¼ºå°‘ id, customerName æˆ– itemsï¼‰', 'error');
          return;
        }

        let finalId = (parsed.id || 'QT-UNKNOWN').trim();
        let wasConflict = false;
        let counter = 1;
        while (quotations.some(q => q.id === finalId)) {
          finalId = `${parsed.id?.trim()}_NEW${counter}`;
          counter++;
          wasConflict = true;
        }

        const migratedParsed = migrateQuotation(parsed as Quotation);
        const firstVo = migratedParsed.variationOrders && migratedParsed.variationOrders.length > 0 ? migratedParsed.variationOrders[0] : null;

        const importedQuoteObj: Quotation = {
          id: finalId,
          customerName: (parsed.customerName || 'æœªå‘½åå®¢æˆ¶').trim(),
          phone: parsed.phone || '',
          address: parsed.address || '',
          date: parsed.date || new Date().toISOString().split('T')[0],
          status: parsed.status || 'pending',
          version: parsed.version || 'v1.0',
          items: parsed.items,
          remarks: parsed.remarks || settings.defaultTerms,
          discount: parsed.discount || 0,
          discountTargetItemId: parsed.discountTargetItemId,
          enableDiscounts: parsed.enableDiscounts,
          discounts: parsed.discounts,
          depositPercent: parsed.depositPercent ?? 40,
          progressPercent: parsed.progressPercent ?? 40,
          balancePercent: parsed.balancePercent ?? 20,
          paymentStages: parsed.paymentStages,
          meetingRecords: parsed.meetingRecords || '',
          draftRemarks: parsed.draftRemarks || '',
          internalNumber: parsed.internalNumber || '',
          hasVO: parsed.hasVO ?? (migratedParsed.variationOrders ? migratedParsed.variationOrders.length > 0 : false),
          voItems: parsed.voItems || (firstVo ? firstVo.items : []),
          voPaymentStages: parsed.voPaymentStages || (firstVo ? firstVo.paymentStages : undefined),
          voRemarks: parsed.voRemarks || (firstVo ? firstVo.remarks : undefined),
          voDiscount: parsed.voDiscount || (firstVo ? firstVo.discount : 0),
          voTitle: parsed.voTitle || (firstVo ? firstVo.title : undefined),
          variationOrders: migratedParsed.variationOrders || []
        };

        const updatedQuotes = [importedQuoteObj, ...quotations];
        saveQuotationToFirestore(importedQuoteObj)
          .catch(err => console.error("Firestore save error on import:", err));
        
        syncQuotes(updatedQuotes, true);

        if (wasConflict) {
          showToast(`æˆåŠŸå°å…¥å ±åƒ¹å–®ï¼å·²æ’é™¤å–®è™Ÿè¡çªï¼Œè‡ªå‹•é‡å‘½åç‚ºï¼š${finalId}`, 'info');
        } else {
          showToast(`æˆåŠŸå°å…¥å ±åƒ¹å–®ï¼(ç·¨è™Ÿ: ${finalId})`, 'success');
        }
      } catch (err) {
        showToast('å°å…¥ JSON å ±åƒ¹å–®å¤±æ•—ï¼Œå¯èƒ½æª”æ¡ˆå·²æå£ï¼', 'error');
        console.error("Error importing single quote JSON file:", err);
      }
    };
    fileReader.readAsText(files[0]);
    event.target.value = ''; // Reset file input
  };

  // Export CSV for single quotation
  const handleExportQuoteCSV = (quote: Quotation) => {
    const financials = getQuoteFinancials(quote);
    let csvContent = "\ufeff"; // UTF-8 BOM
    
    // Headers
    csvContent += `å ±åƒ¹å–®è™Ÿ,${quote.id}\r\n`;
    csvContent += `å®¢æˆ¶å§“å,${quote.customerName}\r\n`;
    csvContent += `è¯çµ¡é›»è©±,${quote.phone}\r\n`;
    csvContent += `è£ä¿®åœ°å€,${quote.address}\r\n`;
    csvContent += `ç·¨è£½æ—¥æœŸ,${quote.date}\r\n`;
    csvContent += `ç›®å‰ç‹€æ…‹,${getStatusLabel(quote.status)}\r\n`;
    csvContent += `ç‰ˆæœ¬æ¨™è¨˜,${quote.version}\r\n\r\n`;
    
    csvContent += "å·¥ç¨‹é …ç›®åˆ†é¡,é …ç›®åç¨±,å–®ä½,æ•¸é‡,å–®åƒ¹,å°è¨ˆ (HKD),å‚™è¨»èªªæ˜\r\n";
    
    // Group and output
    const quoteCategories = getQuotationCategories(quote, categories);
    quoteCategories.forEach(cat => {
      const items = quote.items.filter(i => i.category === cat);
      if (items.length > 0) {
        items.forEach(i => {
          const rowPrice = i.unitPrice;
          const rowSub = i.quantity * rowPrice;
          const cleanName = i.name.replace(/,/g, 'ï¼Œ');
          const cleanRemark = i.remark.replace(/,/g, 'ï¼Œ').replace(/\n/g, ' ï¼› ');
          csvContent += `${cat},${cleanName},${i.unit},${i.quantity},${rowPrice},${rowSub},${cleanRemark}\r\n`;
        });
      }
    });

    if (quote.enableDiscounts && quote.discounts && quote.discounts.length > 0) {
      csvContent += `,,,,,åŸåƒ¹å°è¨ˆ,${financials.subtotal}\r\n`;
      quote.discounts.forEach(d => {
        const discountItemName = d.targetItemId ? (quote.items.find(i => i.id === d.targetItemId || i.name === d.targetItemId)?.name || d.targetItemId) : 'æ•´é«”åˆç´„';
        csvContent += `,,,,,ç‰¹åˆ¥æŠ˜æ‰£ (${discountItemName}),-${d.amount}\r\n`;
      });
    } else if (quote.discount > 0) {
      const discountItemName = quote.discountTargetItemId ? (quote.items.find(i => i.id === quote.discountTargetItemId || i.name === quote.discountTargetItemId)?.name || quote.discountTargetItemId) : 'æ•´é«”åˆç´„';
      csvContent += `,,,,,åŸåƒ¹å°è¨ˆ,${financials.subtotal}\r\n`;
      csvContent += `,,,,,ç‰¹åˆ¥æŠ˜æ‰£ (${discountItemName}),-${quote.discount}\r\n`;
    }
    csvContent += `,,,,,åˆè¨ˆæ·¨å€¼,${financials.grandTotal}\r\n`;
    
    // Payment breakdown
    csvContent += `\r\nè¨‚é‡‘åˆ†é…è¦åŠƒ (${quote.depositPercent}%),${financials.depositVal}\r\n`;
    csvContent += `ä¸­æœŸå·¥ç¨‹æ¬¾åˆ†é… (${quote.progressPercent}%),${financials.progressVal}\r\n`;
    csvContent += `å®Œå·¥çµç®—å°¾æ¬¾ (${quote.balancePercent}%),${financials.balanceVal}\r\n`;

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `è£ä¿®å ±åƒ¹å–®_${quote.customerName}_${quote.id}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    showToast('å ±åƒ¹å–® CSV è³‡æ–™ç°¿å·²æˆåŠŸä¸‹è¼‰');
  };

